return ['domain'=>'wpml-import','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Ein Mehrzweck-Plugin zum Exportieren und Importieren von mehrsprachigen Inhalten.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'Der Import-Trigger akzeptiert den Key nicht mehr in der URL. Senden Sie ihn in einem POST-Body.','Method Not Allowed'=>'Methode nicht erlaubt','Unauthorized'=>'Nicht autorisiert','No items to process'=>'Keine Elemente zu verarbeiten','No Content'=>'Kein Inhalt','Import process completed'=>'Importvorgang abgeschlossen','Success'=>'Erfolg','Import process failed'=>'Importvorgang fehlgeschlagen','Internal Server Error'=>'Interner Serverfehler','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d Element konnte nicht verarbeitet werden und wurde übersprungen.' . "\0" . '%1$s: %2$d Elemente konnten nicht verarbeitet werden und wurden übersprungen.','Cleaning Up Post Data'=>'Bereinigung von Beitragsdaten','Removing temporary and import-related post meta data.'=>'Entfernen von temporären und importbezogenen Beitrags-Metadaten.','Cleaning Up Term Data'=>'Bereinigung von Begriffsdaten','Removing temporary and import-related term meta data.'=>'Entfernen von temporären und importbezogenen Begriff-Metadaten.','Connecting Post Image Attachments'=>'Verknüpfung von Beitrags-Bildanhängen','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'Aktualisierung von Beitragsbild- und Galerie-Anhang-IDs bei übersetzten Beiträgen, Produkten und CPTs, um auf deren übersetzte Entsprechungen zu verweisen.','Connecting Inline Term Translations'=>'Verknüpfung von Inline-Begriffsübersetzungen','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Scannen von Beiträgen mit einem einzelnen Taxonomie-Begriff, um die diesen Beiträgen zugewiesenen Begriffe zu identifizieren und mit ihren Übersetzungen zu verknüpfen.','Deleting Obsolete Original Terms'=>'Löschen veralteter Originalbegriffe','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Entfernen von Originalbegriffen, die nach dem Erstellen von Duplikaten für gleichnamige Begriffe nicht mehr benötigt werden. Sicherstellen, dass keine Beiträge mit diesen Originalbegriffen verknüpft sind.','Duplicating Terms with Shared Names Across Languages'=>'Duplizieren von Begriffen mit gemeinsamen Namen über Sprachen hinweg','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Erstellen von Duplikaten in der richtigen Sprache für Begriffe, die denselben Namen in verschiedenen Sprachen haben, aber zu Beiträgen in unterschiedlichen Sprachen gehören.','Fixing Imported Post Slugs'=>'Korrektur importierter Beitrags-Slugs','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Regenerierung übersetzter Beitrags-Slugs, um Konflikte mit den Originalen zu vermeiden.','Clearing Translations Cache'=>'Bereinigung des Übersetzungscaches','Invalidating the persistent cache so it can be regenerated.'=>'Invalidierung des persistenten Caches, damit dieser neu generiert werden kann.','Marking Parent Terms for Connection'=>'Markierung von Eltern-Begriffen für die Verknüpfung','Collecting parent terms to connect their translations in the next step.'=>'Sammeln von Eltern-Begriffen, um deren Übersetzungen im nächsten Schritt zu verknüpfen.','Connecting Posts with Correct Term Translations'=>'Verknüpfung von Beiträgen mit korrekten Begriffsübersetzungen','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Sicherstellen, dass Beiträge mit Begriffen in der richtigen Sprache verknüpft sind, insbesondere wenn Sie dieselben Begriffsnamen in verschiedenen Sprachen haben.','Sending Posts for Automatic Translation'=>'Versand von Beiträgen zur automatischen Übersetzung','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Erstellen von automatischen Übersetzungsaufträgen für Beiträge, die in den exportierten Daten für die automatische Übersetzung markiert wurden.','Setting Attachments\' Language'=>'Festlegen der Sprache von Anhängen','Assigning a language to imported attachments.'=>'Zuweisen einer Sprache zu importierten Anhängen.','Updating Final Post Status'=>'Aktualisierung des finalen Beitragsstatus','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'Festlegen des Beitragsstatus basierend auf dem Feld „_wpml_import_after_process_post_status“ aus der Importdatei (falls vorhanden).','Identifying Inline Term Languages'=>'Identifizierung von Inline-Begriffssprachen','Identifying and setting the language of terms created during post imports.'=>'Identifizierung und Festlegung der Sprache von Begriffen, die während des Beitragsimports erstellt wurden.','Setting Posts’ Language'=>'Festlegen der Sprache von Beiträgen','Connecting posts to the default language and translations.'=>'Verknüpfung von Beiträgen mit der Standardsprache und den Übersetzungen.','Setting Terms’ Language'=>'Festlegen der Sprache von Begriffen','Connecting taxonomy terms to the default (original) language and translations.'=>'Verknüpfung von Taxonomie-Begriffen mit der Standard- (Original-) Sprache und den Übersetzungen.','Setting Parent Terms\' Language'=>'Festlegen der Sprache von Eltern-Begriffen','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Zuweisen der Sprache zu Eltern-Taxonomie-Begriffen, die keine haben, basierend auf der Sprache, die ihren Kindern zugewiesen wurde.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'Migrieren Sie Ihre mehrsprachige Website? Denken Sie daran, auch %s auf Ihrer neuen Website zu installieren, bevor Sie Ihre Inhalte importieren, damit wir alle Übersetzungen wiederherstellen können.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Migrieren Sie Ihren mehrsprachigen Shop? Mit %1$s und %2$s können Sie Ihre übersetzten Inhalte auf eine neue Website übertragen, einschließlich Querverkäufen, Zusatzverkäufen und Produktattributen.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Migrieren Sie Ihren mehrsprachigen Shop? Denken Sie daran, %1$s und %2$s auf Ihrer neuen Website zu installieren, bevor Sie Ihre Inhalte importieren, damit wir alle Übersetzungen wiederherstellen können.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Möchten Sie Ihre mehrsprachigen Inhalte importieren? Denken Sie daran, %s auf Ihrer Original-Website zu installieren, bevor Sie deren Inhalte exportieren, damit wir alle Übersetzungen hier importieren können.','Looking to import your multilingual content? Install %1$s on this site.'=>'Möchten Sie Ihre mehrsprachigen Inhalte importieren? Installieren Sie %1$s auf dieser Website.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Denken Sie daran, auch %2$s und %3$s in Ihrem Original-Shop zu aktivieren, bevor Sie dessen Inhalte exportieren, damit wir alle Übersetzungen hier importieren können.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Möchten Sie Ihre mehrsprachigen Inhalte importieren? Denken Sie daran, %1$s und %2$s in Ihrem Original-Shop zu aktivieren, bevor Sie dessen Inhalte exportieren, damit wir alle Übersetzungen hier importieren können.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Zu allen Sprachen wechseln','Linking Product Attribute Translations'=>'Verknüpfung von Produktattribut-Übersetzungen','Connecting product attributes to their translations based on associated product variations.'=>'Verknüpfung von Produktattributen mit ihren Übersetzungen basierend auf zugehörigen Produktvariationen.','Updating Related Products On Translations'=>'Aktualisierung verwandter Produkte in Übersetzungen','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Einrichten von Zusatzverkäufen, Querverkäufen und Referenzen für gruppierte Produkte in der richtigen Sprache.','Importing Custom Attribute Labels'=>'Importieren benutzerdefinierter Attributbeschriftungen','Importing labels for product-specific (custom) attributes from the exported data.'=>'Importieren von Beschriftungen für produktspezifische (benutzerdefinierte) Attribute aus den exportierten Daten.','You are about to export all your products in all languages at once.'=>'Sie sind dabei, alle Ihre Produkte in allen Sprachen gleichzeitig zu exportieren.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Denken Sie daran, %1$s und %2$s auf Ihrer neuen Website zu installieren, bevor Sie Ihre Inhalte importieren, damit wir alle Übersetzungen wiederherstellen können.','You are about to export your products in %s.'=>'Sie sind dabei, Ihre Produkte auf %s zu exportieren.','Registering Product Attributes'=>'Registrierung von Produktattributen','Identifying and registering attributes created during product imports for translation.'=>'Identifizierung und Registrierung von Attributen, die während des Produktimports erstellt wurden, für die Übersetzung.','Identifying Product Attribute Languages'=>'Identifizierung von Produktattribut-Sprachen','Identifying and setting the language of attributes created during product imports.'=>'Identifizierung und Festlegung der Sprache von Attributen, die während des Produktimports erstellt wurden.','Export and Import'=>'Export und Import','I’m using the built-in %s export/import tool'=>'Ich verwende das integrierte %s Export-/Import-Tool','I’m using %s plugin'=>'Ich verwende das Plugin %s','(%1$d/%2$d items)'=>'(%1$d/%2$d Elemente)','%d skipped'=>'%d übersprungen','(no items)'=>'(keine Elemente)','Counting items...'=>'Elemente werden gezählt...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Sagen Sie uns zuerst, wie Sie die Inhalte erstellen werden, die Sie importieren möchten:','Continue'=>'Weiter','I’m using %1$s and %2$s plugins'=>'Ich verwende die Plugins %1$s und %2$s','I’m using a different method to export from this site'=>'Ich verwende eine andere Methode für den Export von dieser Website','I’m exporting the content from this site'=>'Ich exportiere die Inhalte von dieser Website','I’m exporting the content from a different website or system'=>'Ich exportiere die Inhalte von einer anderen Website oder einem anderen System','Before importing, add language columns to your content'=>'Fügen Sie Ihren Inhalten vor dem Import Sprachspalten hinzu','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Stellen Sie sicher, dass Ihre Importdatei die folgenden Spalten (benutzerdefinierte Felder) mit Sprachinformationen enthält:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: Ein Wert, der für alle Übersetzungen jedes Elements gleich ist. Bei E-Commerce-Websites ist dies oft die SKU.','%s: The language code for each item.'=>'%s: Der Sprachcode für jedes Element.','And, you can include these two columns if needed:'=>'Und Sie können bei Bedarf diese beiden Spalten hinzufügen:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: Wenn dieses Element eine Übersetzung ist, setzen Sie diese Spalte auf den Code der Quellsprache. Wenn es keine Übersetzung ist, lassen Sie sie leer.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: Auf „draft“ oder „published“ setzen, um den Veröffentlichungsstatus des Beitrags nach der Sprachanpassung festzulegen. Normalerweise ist dieser Wert „published“.','Here is an example of importing two items, into your site’s languages (%s):'=>'Hier ist ein Beispiel für den Import von zwei Elementen in die Sprachen Ihrer Website (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'Sobald Sie Ihrer mehrsprachigen Inhaltsdatei Sprachspalten hinzugefügt haben, importieren Sie diese mit einem beliebigen Import-Plugin Ihrer Wahl auf Ihre Website.','Before importing, your content needs language information'=>'Vor dem Import benötigen Ihre Inhalte Sprachinformationen','%s will add the necessary language information to your export.'=>'%s wird Ihrem Export die erforderlichen Sprachinformationen hinzufügen.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Importieren Sie Ihre mehrsprachige Inhaltsdatei mit einem beliebigen Import-Plugin Ihrer Wahl in die Website.','Use your favorite import plugin'=>'Verwenden Sie Ihr bevorzugtes Import-Plugin','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'Nachdem Sie den Inhalt importiert haben, wird er noch nicht die korrekten Sprachinformationen anzeigen. Daher empfehlen wir, neue Inhalte als Entwürfe zu importieren. Wenn Sie Aktualisierungen importieren, können Sie bereits veröffentlichte Inhalte als veröffentlicht beibehalten.','Return here, to %s, to set languages and connect translations'=>'Kehren Sie hierher zu %s zurück, um Sprachen festzulegen und Übersetzungen zu verknüpfen','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Wenn Sie diese Seite besuchen, nachdem Sie Inhalte mit Sprachinformationen importiert haben, können Sie %s ausführen, um Sprachen zuzuweisen und Übersetzungen zu verknüpfen.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Bereits importiert und Sie sehen immer noch diesen Bildschirm? %1$sFehlerbehebung %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'So exportieren und importieren Sie Inhalte in mehreren Sprachen','%s is ready to update your imported content'=>'%s ist bereit, Ihre importierten Inhalte zu aktualisieren','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Gute Arbeit. Wir sehen %1$d Begriffe und %2$d Beiträge, die importiert wurden und Sprachinformationen benötigen.','Good job. We see %d terms that are imported and need language information.'=>'Gute Arbeit. Wir sehen %d Begriffe, die importiert wurden und Sprachinformationen benötigen.','Good job. We see %d posts that are imported and need language information.'=>'Gute Arbeit. Wir sehen %d Beiträge, die importiert wurden und Sprachinformationen benötigen.','Run WPML Import'=>'WPML Import ausführen','Multilingual Import Complete'=>'Mehrsprachiger Import abgeschlossen']];